import pygame
import math
import random
import sys
import array

# ============================================================
# BUBBLE SHOOTER - FINAL BMW EDITION
# ============================================================

pygame.mixer.pre_init(frequency=44100, size=-16, channels=1, buffer=512)
pygame.init()

WIDTH, HEIGHT = 900, 700
screen = pygame.display.set_mode((WIDTH, HEIGHT))
pygame.display.set_caption("Bubble Shooter")
clock = pygame.time.Clock()
FPS = 60

# ---------------- COLORS ----------------
BG_TOP = (8, 12, 35)
BG_BOTTOM = (42, 18, 70)
BOARD_COLOR = (18, 24, 52)
BORDER_COLOR = (135, 115, 210)
WHITE = (255, 255, 255)
GRAY = (170, 175, 200)
RED = (235, 65, 75)
GREEN = (65, 205, 105)
BLUE = (65, 135, 240)
YELLOW = (245, 205, 60)
PURPLE = (165, 85, 220)
ORANGE = (245, 135, 50)
PINK = (235, 90, 165)

BUBBLE_COLORS = [RED, GREEN, BLUE, YELLOW, PURPLE, ORANGE, PINK]

# ---------------- FONTS ----------------
font_title = pygame.font.SysFont("arial", 36, bold=True)
font_huge = pygame.font.SysFont("arial", 54, bold=True)
font_large = pygame.font.SysFont("arial", 34, bold=True)
font_medium = pygame.font.SysFont("arial", 22, bold=True)
font_small = pygame.font.SysFont("arial", 16)
font_button = pygame.font.SysFont("arial", 20, bold=True)

# ---------------- BOARD ----------------
BOARD_LEFT, BOARD_RIGHT = 50, 850
BOARD_TOP, BOARD_BOTTOM = 75, 600
DANGER_LINE_Y = 570

RADIUS = 18
DIAMETER = RADIUS * 2
ROW_HEIGHT = 34
SHOOTER_X, SHOOTER_Y = WIDTH // 2, 650

# ---------------- LEVEL SETTINGS ----------------
level = 1
MAX_LEVEL = 10
level_message_timer = 0

# ---------------- GAME VARIABLES ----------------
bubbles = []
current_color = None
next_color = None
shot_bubble = None
score = 0
shots_left = 12
combo = 0
game_over = False
game_won = False
paused = False
popping_bubbles = []

# Decorative background bubbles
background_bubbles = []
for _ in range(35):
    background_bubbles.append({
        "x": random.randint(0, WIDTH),
        "y": random.randint(0, HEIGHT),
        "r": random.randint(8, 35),
        "speed": random.uniform(0.15, 0.5),
        "color": random.choice(BUBBLE_COLORS),
    })

# ---------------- SOUND ----------------
pop_sound = None

def create_pop_sound():
    global pop_sound
    try:
        sample_rate = 44100
        duration = 0.13
        samples = int(sample_rate * duration)
        data = array.array("h")
        for i in range(samples):
            t = i / sample_rate
            frequency = 750 - 600 * (t / duration)
            envelope = 1 - (t / duration)
            value = math.sin(2 * math.pi * frequency * t)
            data.append(int(value * envelope * 13000))
        pop_sound = pygame.mixer.Sound(buffer=data.tobytes())
        pop_sound.set_volume(0.35)
    except Exception:
        pop_sound = None

def play_pop_sound():
    if pop_sound:
        try:
            pop_sound.play()
        except Exception:
            pass

create_pop_sound()

# ============================================================
# HELPERS
# ============================================================

def draw_text(text, font, color, x, y, center=True):
    surface = font.render(text, True, color)
    rect = surface.get_rect(center=(x, y)) if center else surface.get_rect(topleft=(x, y))
    screen.blit(surface, rect)

def distance(x1, y1, x2, y2):
    return math.hypot(x2 - x1, y2 - y1)

def button(rect, text, mouse_pos, active=True):
    hover = rect.collidepoint(mouse_pos) and active
    color = (80, 95, 170) if hover else (50, 60, 115)
    pygame.draw.rect(screen, color, rect, border_radius=12)
    pygame.draw.rect(screen, BORDER_COLOR, rect, 2, border_radius=12)
    draw_text(text, font_button, WHITE, rect.centerx, rect.centery)
    return hover

# ============================================================
# EMBEDDED BMW WALLPAPER
# ============================================================

import base64
import io

BMW_WALLPAPER_DATA = """"""

try:
    _wallpaper_bytes = base64.b64decode(BMW_WALLPAPER_DATA)
    wallpaper_image = pygame.image.load(
        io.BytesIO(_wallpaper_bytes)
    ).convert()
    wallpaper_image = pygame.transform.smoothscale(
        wallpaper_image, (WIDTH, HEIGHT)
    )
except Exception:
    wallpaper_image = None

# ============================================================
# BACKGROUND WALLPAPER
# ============================================================

def draw_background():
    """Draw the embedded BMW wallpaper across the whole game."""
    if wallpaper_image is not None:
        screen.blit(wallpaper_image, (0, 0))

        # Dark transparent layer so the game UI remains readable.
        overlay = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
        overlay.fill((0, 0, 0, 95))
        screen.blit(overlay, (0, 0))

        # Very subtle blue/purple cinematic tint.
        tint = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
        tint.fill((25, 20, 65, 30))
        screen.blit(tint, (0, 0))
    else:
        # Fallback background if the embedded image cannot be loaded.
        for y in range(HEIGHT):
            t = y / HEIGHT
            color = (
                int(BG_TOP[0] * (1 - t) + BG_BOTTOM[0] * t),
                int(BG_TOP[1] * (1 - t) + BG_BOTTOM[1] * t),
                int(BG_TOP[2] * (1 - t) + BG_BOTTOM[2] * t),
            )
            pygame.draw.line(screen, color, (0, y), (WIDTH, y))

    # A few subtle floating bubbles over the wallpaper.
    for b in background_bubbles:
        c = tuple(max(0, min(255, int(v * 0.18))) for v in b["color"])
        pygame.draw.circle(
            screen,
            c,
            (int(b["x"]), int(b["y"])),
            b["r"],
            2
        )


def update_background():
    for b in background_bubbles:
        b["y"] -= b["speed"]
        if b["y"] < -b["r"]:
            b["y"] = HEIGHT + b["r"]
            b["x"] = random.randint(0, WIDTH)

# ============================================================
# BUBBLE
# ============================================================

class Bubble:
    def __init__(self, x, y, color):
        self.x = float(x)
        self.y = float(y)
        self.color = color
        self.vx = 0
        self.vy = 0

    def draw(self):
        pygame.draw.circle(screen, self.color, (int(self.x), int(self.y)), RADIUS)
        pygame.draw.circle(screen, WHITE, (int(self.x - 6), int(self.y - 7)), 4)
        darker = tuple(max(0, c - 55) for c in self.color)
        pygame.draw.circle(screen, darker, (int(self.x), int(self.y)), RADIUS, 2)

# ============================================================
# GRID / BOARD
# ============================================================

def grid_position(row, col):
    x = BOARD_LEFT + RADIUS + col * DIAMETER
    if row % 2 == 1:
        x += RADIUS
    y = BOARD_TOP + RADIUS + row * ROW_HEIGHT
    return x, y

def create_initial_bubbles():
    global bubbles
    bubbles = []

    # Higher levels = more rows and more colors
    rows = min(8 + (level - 1) // 2, 12)
    cols = 21
    hole_chance = min(0.12 + level * 0.01, 0.22)
    colors = BUBBLE_COLORS[:min(6 + level // 3, 7)]

    for row in range(rows):
        for col in range(cols):
            x, y = grid_position(row, col)
            if row >= 4 and random.random() < hole_chance:
                continue
            bubbles.append(Bubble(x, y, random.choice(colors)))

# ============================================================
# MATCHING / FLOATING
# ============================================================

def get_neighbors(target):
    return [
        b for b in bubbles
        if b is not target and distance(target.x, target.y, b.x, b.y) <= DIAMETER + 5
    ]

def find_matching_group(start):
    group = []
    visited = set()
    stack = [start]

    while stack:
        current = stack.pop()
        if id(current) in visited:
            continue
        visited.add(id(current))

        if current.color != start.color:
            continue

        group.append(current)
        for neighbor in get_neighbors(current):
            if id(neighbor) not in visited:
                stack.append(neighbor)
    return group

def remove_floating_bubbles():
    connected = set()
    stack = [b for b in bubbles if b.y <= BOARD_TOP + RADIUS + 5]

    while stack:
        current = stack.pop()
        if id(current) in connected:
            continue
        connected.add(id(current))
        for neighbor in get_neighbors(current):
            if id(neighbor) not in connected:
                stack.append(neighbor)

    floating = [b for b in bubbles if id(b) not in connected]
    for b in floating:
        if b in bubbles:
            bubbles.remove(b)
        add_pop_animation(b)

    if floating:
        play_pop_sound()
    return len(floating)

# ============================================================
# POP ANIMATION
# ============================================================

def add_pop_animation(bubble):
    popping_bubbles.append({
        "x": bubble.x, "y": bubble.y,
        "color": bubble.color, "radius": RADIUS, "alpha": 255
    })

def update_pop_animation():
    for item in popping_bubbles[:]:
        item["radius"] += 2.3
        item["alpha"] -= 20
        if item["alpha"] <= 0:
            popping_bubbles.remove(item)

def draw_pop_animation():
    for item in popping_bubbles:
        radius = int(item["radius"])
        if radius <= 1:
            continue
        surface = pygame.Surface((radius * 2 + 12, radius * 2 + 12), pygame.SRCALPHA)
        color = (*item["color"], max(0, item["alpha"]))
        pygame.draw.circle(surface, color, (radius + 6, radius + 6), radius, 3)
        screen.blit(surface, (int(item["x"] - radius - 6), int(item["y"] - radius - 6)))

# ============================================================
# SHOOTING
# ============================================================

def get_aim_direction():
    mouse_x, mouse_y = pygame.mouse.get_pos()
    dx = float(mouse_x - SHOOTER_X)
    dy = float(mouse_y - SHOOTER_Y)
    length = math.hypot(dx, dy)

    if length < 0.0001:
        return 0.0, -1.0

    dx /= length
    dy /= length

    if dy > -0.15:
        dy = -0.15
        length = math.hypot(dx, dy)
        dx /= length
        dy /= length

    return dx, dy

def draw_aim_path():
    if shot_bubble is not None or paused:
        return

    dx, dy = get_aim_direction()
    x, y = float(SHOOTER_X), float(SHOOTER_Y)
    points = [(x, y)]
    remaining = 520

    for _ in range(3):
        if abs(dx) < 0.0001:
            wall_distance = float("inf")
        elif dx > 0:
            wall_distance = (BOARD_RIGHT - RADIUS - x) / dx
        else:
            wall_distance = (BOARD_LEFT + RADIUS - x) / dx

        if dy < -0.0001:
            ceiling_distance = (BOARD_TOP + RADIUS - y) / dy
        else:
            ceiling_distance = float("inf")

        distances = [remaining]
        if wall_distance > 0:
            distances.append(abs(wall_distance))
        if ceiling_distance > 0:
            distances.append(abs(ceiling_distance))

        step = min(distances)
        if step < 0.1:
            break

        x += dx * step
        y += dy * step
        points.append((x, y))
        remaining -= step

        if y <= BOARD_TOP + RADIUS + 1:
            break

        if x <= BOARD_LEFT + RADIUS + 1 or x >= BOARD_RIGHT - RADIUS - 1:
            dx *= -1
            x += dx * 1.5
        else:
            break

        if remaining <= 0:
            break

    for i in range(len(points) - 1):
        x1, y1 = points[i]
        x2, y2 = points[i + 1]
        length = distance(x1, y1, x2, y2)
        dots = max(1, int(length / 14))

        for j in range(1, dots + 1):
            ratio = j / dots
            px = x1 + (x2 - x1) * ratio
            py = y1 + (y2 - y1) * ratio
            pygame.draw.circle(screen, (205, 210, 235), (int(px), int(py)), 3)

def find_best_position():
    if shot_bubble is None:
        return None

    candidates = []
    for row in range(18):
        for col in range(21):
            x, y = grid_position(row, col)

            if y + RADIUS >= DANGER_LINE_Y:
                continue

            valid = True
            for bubble in bubbles:
                if distance(x, y, bubble.x, bubble.y) < DIAMETER - 2:
                    valid = False
                    break

            if valid:
                d = distance(shot_bubble.x, shot_bubble.y, x, y)
                candidates.append((d, x, y))

    if not candidates:
        return None

    candidates.sort(key=lambda item: item[0])
    return candidates[0]

def place_shot_bubble():
    global shot_bubble, current_color, next_color
    global score, shots_left, combo, game_won, game_over

    if shot_bubble is None:
        return

    position = find_best_position()
    if position is None:
        game_over = True
        shot_bubble = None
        return

    _, x, y = position
    shot_bubble.x, shot_bubble.y = x, y
    bubbles.append(shot_bubble)

    group = find_matching_group(shot_bubble)

    if len(group) >= 3:
        combo += 1
        score += len(group) * 10 + combo * 5

        for bubble in group:
            if bubble in bubbles:
                bubbles.remove(bubble)
                add_pop_animation(bubble)

        play_pop_sound()

        floating = remove_floating_bubbles()
        score += floating * 20

        if len(group) >= 5:
            score += 50
    else:
        combo = 0
        shots_left -= 1

    if len(bubbles) == 0:
        game_won = True

    current_color = next_color
    colors = BUBBLE_COLORS[:min(6 + level // 3, 7)]
    next_color = random.choice(colors)
    shot_bubble = None

def shoot():
    global shot_bubble

    if paused or shot_bubble is not None or game_over or game_won:
        return

    dx, dy = get_aim_direction()
    shot_bubble = Bubble(SHOOTER_X, SHOOTER_Y, current_color)

    # Slightly faster shooting on higher levels
    speed = 11 + min(level - 1, 5) * 0.5
    shot_bubble.vx = dx * speed
    shot_bubble.vy = dy * speed

def update_shot():
    global shot_bubble

    if shot_bubble is None:
        return

    shot_bubble.x += shot_bubble.vx
    shot_bubble.y += shot_bubble.vy

    if shot_bubble.x <= BOARD_LEFT + RADIUS:
        shot_bubble.x = BOARD_LEFT + RADIUS
        shot_bubble.vx = abs(shot_bubble.vx)
    elif shot_bubble.x >= BOARD_RIGHT - RADIUS:
        shot_bubble.x = BOARD_RIGHT - RADIUS
        shot_bubble.vx = -abs(shot_bubble.vx)

    if shot_bubble.y <= BOARD_TOP + RADIUS:
        shot_bubble.y = BOARD_TOP + RADIUS
        place_shot_bubble()
        return

    for bubble in bubbles:
        if distance(shot_bubble.x, shot_bubble.y, bubble.x, bubble.y) <= DIAMETER - 2:
            place_shot_bubble()
            return

# ============================================================
# BUBBLE SWITCH
# ============================================================

def switch_bubbles():
    global current_color, next_color

    if paused or shot_bubble is not None or game_over or game_won:
        return

    current_color, next_color = next_color, current_color

# ============================================================
# LEVEL SYSTEM
# ============================================================

def start_level(new_level):
    global level, score, shots_left, combo
    global game_over, game_won, paused
    global shot_bubble, popping_bubbles
    global current_color, next_color, level_message_timer

    level = max(1, min(new_level, MAX_LEVEL))
    score = score if level > 1 else 0

    # Fewer shots at higher levels
    shots_left = max(7, 13 - level)
    combo = 0
    game_over = False
    game_won = False
    paused = False
    shot_bubble = None
    popping_bubbles = []

    colors = BUBBLE_COLORS[:min(6 + level // 3, 7)]
    current_color = random.choice(colors)
    next_color = random.choice(colors)

    create_initial_bubbles()
    level_message_timer = 120

def next_level():
    if level < MAX_LEVEL:
        start_level(level + 1)
    else:
        # Completing level 10 starts a fresh level-1 game
        start_level(1)

def restart_game():
    start_level(1)

# ============================================================
# DRAWING
# ============================================================

def draw_board():
    """Transparent glass play area with the BMW wallpaper visible behind it."""
    board_w = BOARD_RIGHT - BOARD_LEFT
    board_h = BOARD_BOTTOM - BOARD_TOP

    glass = pygame.Surface((board_w, board_h), pygame.SRCALPHA)
    glass.fill((8, 12, 25, 75))

    # Soft glass glow
    pygame.draw.rect(
        glass,
        (90, 70, 150, 22),
        (3, 3, board_w - 6, board_h - 6),
        border_radius=15
    )
    screen.blit(glass, (BOARD_LEFT, BOARD_TOP))

    pygame.draw.rect(
        screen,
        (150, 135, 205),
        (BOARD_LEFT, BOARD_TOP, board_w, board_h),
        2,
        border_radius=15
    )

    # Danger line
    pygame.draw.line(
        screen,
        RED,
        (BOARD_LEFT, DANGER_LINE_Y),
        (BOARD_RIGHT, DANGER_LINE_Y),
        4
    )

    for x in range(BOARD_LEFT, BOARD_RIGHT, 25):
        pygame.draw.line(
            screen,
            (255, 120, 140),
            (x, DANGER_LINE_Y),
            (x + 12, DANGER_LINE_Y),
            2
        )

    draw_text(
        "DANGER",
        font_small,
        (255, 145, 160),
        BOARD_RIGHT - 45,
        DANGER_LINE_Y - 18
    )

    for bubble in bubbles:
        bubble.draw()


def draw_shooter():
    pygame.draw.circle(screen, (45, 50, 85), (SHOOTER_X, SHOOTER_Y), 32)
    pygame.draw.circle(screen, WHITE, (SHOOTER_X, SHOOTER_Y), 32, 2)

    pygame.draw.circle(screen, current_color, (SHOOTER_X, SHOOTER_Y), RADIUS)
    pygame.draw.circle(screen, WHITE, (SHOOTER_X - 6, SHOOTER_Y - 7), 4)

def draw_next_bubble():
    box = pygame.Rect(735, 615, 105, 60)
    pygame.draw.rect(screen, (35, 40, 70), box, border_radius=12)
    pygame.draw.rect(screen, BORDER_COLOR, box, 2, border_radius=12)
    draw_text("NEXT", font_small, WHITE, 765, 628)
    pygame.draw.circle(screen, next_color, (813, 645), 15)

def draw_ui():
    draw_text("BUBBLE SHOOTER", font_title, WHITE, WIDTH // 2, 32)
    pygame.draw.line(
        screen, (150, 120, 230),
        (WIDTH // 2 - 150, 53),
        (WIDTH // 2 + 150, 53), 2
    )
    draw_text(f"SCORE: {score}", font_medium, WHITE, 95, 32)
    draw_text(f"LEVEL: {level}", font_medium, YELLOW, 450, 65)
    draw_text(f"SHOTS: {shots_left}", font_medium, WHITE, 790, 32)

    if combo > 1:
        draw_text(f"COMBO x{combo}", font_medium, YELLOW, WIDTH // 2, 635)

    # Pause button
    pause_rect = pygame.Rect(20, 615, 105, 45)
    button(pause_rect, "PAUSE", pygame.mouse.get_pos(), not game_over and not game_won)

def draw_controls():
    draw_text("LEFT CLICK = SHOOT", font_small, GRAY, 155, 682)
    draw_text("SPACE = SWITCH", font_small, GRAY, 365, 682)
    draw_text("P = PAUSE/RESUME", font_small, GRAY, 585, 682)
    draw_text("R = RESTART", font_small, GRAY, 800, 682)

def draw_pause_screen():
    overlay = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
    overlay.fill((0, 0, 20, 205))
    screen.blit(overlay, (0, 0))

    draw_text("GAME PAUSED", font_huge, YELLOW, WIDTH // 2, 230)
    draw_text("Take a break!", font_medium, WHITE, WIDTH // 2, 285)

    resume_rect = pygame.Rect(320, 340, 260, 55)
    restart_rect = pygame.Rect(320, 410, 260, 55)

    button(resume_rect, "RESUME", pygame.mouse.get_pos())
    button(restart_rect, "RESTART", pygame.mouse.get_pos())

    draw_text("Press P to resume", font_small, GRAY, WIDTH // 2, 500)

def draw_end_screen():
    overlay = pygame.Surface((WIDTH, HEIGHT), pygame.SRCALPHA)
    overlay.fill((0, 0, 0, 200))
    screen.blit(overlay, (0, 0))

    if game_won:
        if level < MAX_LEVEL:
            draw_text(f"LEVEL {level} COMPLETE!", font_large, YELLOW, WIDTH // 2, 245)
            draw_text("Great shooting!", font_medium, WHITE, WIDTH // 2, 295)
            draw_text("Click NEXT LEVEL or press N", font_small, GRAY, WIDTH // 2, 330)

            next_rect = pygame.Rect(310, 365, 280, 55)
            button(next_rect, "NEXT LEVEL", pygame.mouse.get_pos())
        else:
            draw_text("YOU BEAT ALL LEVELS!", font_large, YELLOW, WIDTH // 2, 245)
            draw_text("Amazing! You are a Bubble Master!", font_medium, WHITE, WIDTH // 2, 295)
            draw_text("Press R to play again", font_medium, WHITE, WIDTH // 2, 365)
    else:
        draw_text("GAME OVER", font_large, RED, WIDTH // 2, 250)
        draw_text("The bubbles reached the danger line!", font_medium, WHITE, WIDTH // 2, 305)
        draw_text(f"FINAL SCORE: {score}", font_medium, WHITE, WIDTH // 2, 360)
        draw_text("Press R to play again", font_medium, WHITE, WIDTH // 2, 420)

# ============================================================
# MAIN LOOP
# ============================================================

restart_game()
running = True

while running:
    mouse_pos = pygame.mouse.get_pos()

    for event in pygame.event.get():
        if event.type == pygame.QUIT:
            running = False

        elif event.type == pygame.MOUSEBUTTONDOWN and event.button == 1:
            # Pause button
            pause_rect = pygame.Rect(20, 615, 105, 45)

            if not game_over and not game_won and pause_rect.collidepoint(mouse_pos):
                paused = not paused

            # Pause screen buttons
            elif paused:
                resume_rect = pygame.Rect(320, 340, 260, 55)
                restart_rect = pygame.Rect(320, 410, 260, 55)

                if resume_rect.collidepoint(mouse_pos):
                    paused = False
                elif restart_rect.collidepoint(mouse_pos):
                    restart_game()

            # Next level button
            elif game_won and level < MAX_LEVEL:
                next_rect = pygame.Rect(310, 365, 280, 55)
                if next_rect.collidepoint(mouse_pos):
                    next_level()

            # Normal shooting
            elif not game_over and not game_won and not paused:
                shoot()

        elif event.type == pygame.KEYDOWN:
            if event.key == pygame.K_ESCAPE:
                running = False

            elif event.key == pygame.K_p:
                if not game_over and not game_won:
                    paused = not paused

            elif event.key == pygame.K_SPACE:
                if not paused:
                    switch_bubbles()

            elif event.key == pygame.K_r:
                restart_game()

            elif event.key == pygame.K_n:
                if game_won and level < MAX_LEVEL:
                    next_level()

    # ---------------- UPDATE ----------------
    update_background()

    if not paused:
        update_pop_animation()

        if not game_over and not game_won:
            update_shot()

            if shots_left <= 0 and shot_bubble is None:
                game_over = True

            for bubble in bubbles:
                if bubble.y + RADIUS >= DANGER_LINE_Y:
                    game_over = True
                    break

    # ---------------- DRAW ----------------
    draw_background()
    draw_ui()
    draw_board()
    draw_pop_animation()

    if not game_over and not game_won and not paused:
        draw_aim_path()
        draw_shooter()
        draw_next_bubble()

        if shot_bubble is not None:
            shot_bubble.draw()

    draw_controls()

    if paused:
        draw_pause_screen()
    elif game_over or game_won:
        draw_end_screen()

    pygame.display.flip()
    clock.tick(FPS)

pygame.quit()
sys.exit()